<script setup lang="ts">
import { computed, ref, watch, onUnmounted, nextTick } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ArrowLeft, ArrowRight, Search, X, Quote, UserRound } from '@lucide/vue'
import { useCmsSection } from '../cms/content'
import { services, getPage, safeImage } from '../cms/pages'
import { locale } from '../i18n'
import RichTextContent from '../components/RichTextContent.vue'
const props=defineProps<{slug?:string}>()
const c=useCmsSection('PeoplePage')
const route=useRoute(),router=useRouter()
interface Person {slug:string;name:string;role:string;businessSegment:string;practiceAreas:string[];location:string;category:string;bio:string;imageUrl:string}
const people=ref<Person[]>([]),loading=ref(true),error=ref(false)
const name=ref(''),segment=ref(''),practice=ref(''),location=ref(''),secondary=ref('overview')
const id=computed(()=>locale.value==='id')
const tabs=computed(()=>[{key:'overview',label:c.value.overviewTab},{key:'directory',label:c.value.directoryTab},{key:'executive',label:c.value.executiveTab},{key:'management',label:c.value.managementTab},{key:'advisor',label:c.value.advisorsTab}])
const view=computed(()=>tabs.value.some(t=>t.key===route.query.view)?String(route.query.view):'overview')
const secondaryTabs=computed(()=>[{key:'overview',label:c.value.overviewTab},{key:'experts',label:c.value.expertsTab},{key:'approach',label:c.value.approachTab},{key:'culture',label:c.value.cultureTab}])
const segments=computed(()=>[...new Set(people.value.map(p=>p.businessSegment).filter(Boolean))].sort())
const practices=computed(()=>[...new Set(people.value.flatMap(p=>p.practiceAreas))].sort())
const locations=computed(()=>[...new Set(people.value.map(p=>p.location).filter(Boolean))].sort())
const selected=computed(()=>people.value.find(p=>p.slug===props.slug))
const filtering=computed(()=>!!(name.value.trim()||segment.value||practice.value||location.value))
const filtered=computed(()=>people.value.filter(p=>(['overview','directory'].includes(view.value)||p.category===view.value)&&(!name.value.trim()||p.name.toLocaleLowerCase().includes(name.value.trim().toLocaleLowerCase()))&&(!segment.value||p.businessSegment===segment.value)&&(!practice.value||p.practiceAreas.includes(practice.value))&&(!location.value||p.location===location.value)))
const showResults=computed(()=>view.value!=='overview'||filtering.value)
function reset(){name.value='';segment.value='';practice.value='';location.value=''}
function choose(key:string){reset();router.replace({query:{...route.query,view:key==='overview'?undefined:key}})}
async function focusResults(){
 if(view.value==='overview') await router.replace({query:{...route.query,view:'directory'}})
 await nextTick();document.getElementById('people-results')?.focus()
}
function tabKey(event:KeyboardEvent,index:number){let next=index;if(event.key==='ArrowRight')next=(index+1)%tabs.value.length;else if(event.key==='ArrowLeft')next=(index+tabs.value.length-1)%tabs.value.length;else if(event.key==='Home')next=0;else if(event.key==='End')next=tabs.value.length-1;else return;event.preventDefault();choose(tabs.value[next]!.key);document.getElementById('people-tab-'+next)?.focus()}
let request:AbortController|undefined
async function load(){request?.abort();request=new AbortController();const signal=request.signal;loading.value=true;error.value=false;people.value=[];reset();try{const result=await getPage<{data:Person[]}>('website-people',signal);if(!signal.aborted)people.value=Array.isArray(result.data)?result.data:[]}catch{if(!signal.aborted)error.value=true}finally{if(!signal.aborted)loading.value=false}}
watch(locale,load,{immediate:true})
watch([()=>props.slug,()=>selected.value?.name],()=>{document.title=`${selected.value?.name||c.value.title} | BRIAMCO`})
onUnmounted(()=>request?.abort())
</script>
<template>
<div class="people-page">
  <header class="pp-hero" :style="safeImage(c.heroImage)?{backgroundImage:`linear-gradient(90deg,#071536dc,#07153655),url(${safeImage(c.heroImage)})`}:{}"><div class="ad-wrap pp-hero-title"><h1>{{ selected?.name || c.title }}</h1><p v-if="selected">{{ selected.role }}</p></div><nav v-if="!slug" class="ad-wrap pp-tabs" role="tablist" :aria-label="c.title"><button v-for="(tab,index) in tabs" :id="'people-tab-'+index" :key="tab.key" role="tab" :aria-selected="view===tab.key" :tabindex="view===tab.key?0:-1" aria-controls="people-content" @click="choose(tab.key)" @keydown="tabKey($event,index)">{{ tab.label }}</button></nav></header>
  <section v-if="slug" class="ad-wrap pp-profile"><RouterLink to="/people?view=directory" class="pp-text-link"><ArrowLeft :size="18"/>{{ c.backLabel }}</RouterLink><p v-if="loading" role="status">{{ id?'Memuat profil…':'Loading profile…' }}</p><div v-else-if="error" role="alert"><p>{{ id?'Profil tidak dapat dimuat.':'Profiles could not be loaded.' }}</p><button @click="load">{{ id?'Coba lagi':'Try again' }}</button></div><div v-else-if="selected" class="pp-profile-grid"><div><img v-if="safeImage(selected.imageUrl)" :src="safeImage(selected.imageUrl)" :alt="selected.name" class="pp-photo"/><div v-else class="pp-photo pp-placeholder"><UserRound :size="65" aria-hidden="true"/></div><h2>{{ selected.name }}</h2><p>{{ selected.role }}</p><p>{{ selected.location }}</p><p>{{ selected.businessSegment }}</p><ul><li v-for="area in selected.practiceAreas" :key="area">{{ area }}</li></ul></div><div><h2>{{ c.bioLabel }}</h2><RichTextContent :content="selected.bio"/><RouterLink to="/contact" class="ad-button">{{ c.contactLabel }}<ArrowRight :size="18"/></RouterLink></div></div><p v-else role="alert">{{ id?'Profil ini tidak tersedia.':'This profile is not available.' }}</p></section>
  <template v-else>
    <section class="pp-directory"><form class="ad-wrap" role="search" @submit.prevent="focusResults"><h2>{{ c.directoryTitle }}</h2><label class="pp-name"><span class="pp-sr">{{ c.searchPlaceholder }}</span><input v-model="name" type="search" :placeholder="c.searchPlaceholder"/></label><div class="pp-filters"><label><span class="pp-sr">{{ c.segmentLabel }}</span><select v-model="segment"><option value="">{{ c.segmentLabel }}</option><option v-for="item in segments" :key="item">{{ item }}</option></select></label><label><span class="pp-sr">{{ c.practiceLabel }}</span><select v-model="practice"><option value="">{{ c.practiceLabel }}</option><option v-for="item in practices" :key="item">{{ item }}</option></select></label><label><span class="pp-sr">{{ c.locationLabel }}</span><select v-model="location"><option value="">{{ c.locationLabel }}</option><option v-for="item in locations" :key="item">{{ item }}</option></select></label><button type="submit" :aria-label="id?'Cari tim':'Search people'"><Search :size="21"/></button><button type="button" @click="reset" :aria-label="c.resetLabel"><X :size="21"/></button></div></form></section>
    <section id="people-content" class="ad-wrap pp-content" role="tabpanel" :aria-labelledby="'people-tab-'+tabs.findIndex(t=>t.key===view)">
      <p v-if="loading" role="status">{{ id?'Memuat direktori…':'Loading directory…' }}</p><div v-else-if="error" role="alert"><p>{{ id?'Direktori tidak dapat dimuat. Silakan coba lagi.':'The directory could not be loaded. Please try again.' }}</p><button class="pp-text-link" @click="load">{{ id?'Coba lagi':'Try again' }}</button></div>
      <div v-if="showResults" id="people-results" tabindex="-1"><h2>{{ view==='directory'||view==='overview'?c.allTitle:tabs.find(t=>t.key===view)?.label }}</h2><p v-if="!loading && !error" class="pp-count" role="status">{{ filtered.length }} {{ id?'profil':'profiles' }}</p><div v-if="filtered.length" class="pp-grid"><RouterLink v-for="person in filtered" :key="person.slug" :to="'/people/'+encodeURIComponent(person.slug)" class="pp-card"><img v-if="safeImage(person.imageUrl)" :src="safeImage(person.imageUrl)" :alt="person.name" class="pp-photo" loading="lazy"/><div v-else class="pp-photo pp-placeholder"><UserRound :size="60" aria-hidden="true"/></div><h3>{{ person.name }}</h3><p>{{ person.role }}</p></RouterLink></div><div v-else-if="!loading && !error" class="pp-empty"><h3>{{ people.length?c.noResults:c.emptyTitle }}</h3><p v-if="!people.length">{{ c.emptyBody }}</p><button v-if="filtering" @click="reset" class="pp-text-link">{{ c.resetLabel }}</button><RouterLink v-else to="/contact" class="pp-text-link">{{ c.contactLabel }}<ArrowRight :size="18"/></RouterLink></div></div>
      <template v-else><nav class="pp-secondary" :aria-label="id?'Tentang tim kami':'About our people'"><button v-for="tab in secondaryTabs" :key="tab.key" :class="{active:secondary===tab.key}" :aria-pressed="secondary===tab.key" @click="secondary=tab.key">{{ tab.label }}</button></nav><div class="pp-overview"><div><template v-if="secondary==='overview'"><p class="pp-lead">{{ c.overviewLead }}</p><img v-if="safeImage(c.overviewImage)" :src="safeImage(c.overviewImage)" :alt="c.title" class="pp-overview-image" loading="lazy"/><p>{{ c.overviewBody }}</p><button class="ad-button" @click="choose('directory')">{{ c.directoryTab }}<ArrowRight :size="18"/></button></template><template v-else-if="secondary==='experts'"><h2>{{ c.expertsTab }}</h2><div class="pp-expertise"><RouterLink v-for="s in services" :key="s.slug" :to="'/services/'+s.slug"><h3>{{ s.title }}<ArrowRight :size="18"/></h3><p>{{ s.description }}</p></RouterLink></div></template><template v-else><h2>{{ secondary==='approach'?c.approachTitle:c.cultureTitle }}</h2><p>{{ secondary==='approach'?c.approachBody:c.cultureBody }}</p><RouterLink to="/careers" class="ad-button">{{ id?'Bergabung dengan Kami':'Join Our Team' }}<ArrowRight :size="18"/></RouterLink></template></div><aside class="pp-quote"><Quote :size="37" aria-hidden="true"/><p class="pp-quote-label">{{ c.quoteLabel }}</p><blockquote>{{ c.quote }}</blockquote><strong>{{ c.quoteAuthor }}</strong></aside></div></template>
    </section>
  </template>
</div>
</template>
<style scoped>
.pp-hero{padding-top:160px;min-height:540px;display:flex;flex-direction:column;justify-content:space-between;background-color:#071536;background-size:cover;background-position:center;color:white}.pp-hero-title{margin:0 auto;padding:60px 0 115px}.pp-hero h1{font-size:clamp(48px,6vw,95px);line-height:1.1;letter-spacing:-2.5px;font-weight:600}.pp-hero-title>p{font-size:23px;margin-top:20px}.pp-tabs{display:flex;overflow-x:auto;margin:0 auto;scrollbar-width:thin}.pp-tabs button{white-space:nowrap;padding:18px 20px;background:none;border:0;color:white;font-size:16px;cursor:pointer}.pp-tabs button[aria-selected=true]{background:white;color:#0d80d8;font-weight:600}.pp-tabs button:hover{background:#ffffff20}.pp-tabs button[aria-selected=true]:hover{background:white}.pp-directory{background:linear-gradient(110deg,#e5f1fc,#efedff);padding:60px 0 70px}.pp-directory h2{font-size:29px;letter-spacing:-1px;margin-bottom:40px}.pp-name{display:block;margin-bottom:25px}.pp-directory input,.pp-directory select{width:100%;font:inherit;font-size:16px;color:#566178;border:0;border-bottom:1px solid #9da8bd;border-radius:0;background:transparent;padding:14px 0}.pp-filters{display:grid;grid-template-columns:1fr 1fr 1fr auto auto;gap:30px;align-items:center}.pp-filters button{background:none;border:0;color:#0d80d8;padding:10px;cursor:pointer}.pp-sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}.pp-content{padding-top:65px;padding-bottom:90px}.pp-content h2{font-size:38px;line-height:1.2;letter-spacing:-1px;color:#0d80d8;margin-bottom:30px}.pp-secondary{display:flex;gap:30px;overflow-x:auto;border-bottom:1px solid #cbd0dc;margin-bottom:65px}.pp-secondary button{white-space:nowrap;font-size:16px;padding:0 0 17px;background:none;border:0;border-bottom:2px solid transparent;color:#73798a;cursor:pointer}.pp-secondary button.active{color:#0d80d8;border-color:#0d80d8;font-weight:600}.pp-overview{display:grid;grid-template-columns:minmax(0,2.15fr) minmax(250px,1fr);gap:65px}.pp-lead{font-family:Georgia,serif;font-size:clamp(26px,2.6vw,39px);font-weight:bold;line-height:1.25;background:linear-gradient(110deg,#0784d7,#6453ee);background-clip:text;-webkit-text-fill-color:transparent;margin-bottom:45px}.pp-overview-image{width:100%;aspect-ratio:16/9;object-fit:cover;margin-bottom:30px}.pp-overview>div>p:not(.pp-lead){font-size:18px;line-height:1.7;color:#566178;margin-bottom:30px}.pp-quote{align-self:start;padding:30px;background:linear-gradient(120deg,#e5f1fc,#efedff);border-top:3px solid #0d80d8;border-radius:0 0 35px 0}.pp-quote>svg{color:#0d80d8;margin-bottom:20px}.pp-quote-label{font-size:12px;text-transform:uppercase;letter-spacing:1px;color:#0d80d8;margin-bottom:18px}.pp-quote blockquote{font-family:Georgia,serif;font-size:26px;line-height:1.3;font-weight:bold;margin-bottom:25px}.pp-quote strong{font-size:14px}.pp-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:50px 40px}.pp-photo{width:clamp(140px,16vw,240px);max-width:100%;aspect-ratio:1;object-fit:cover;border-radius:50%;margin-bottom:20px;box-shadow:0 5px 8px #0001}.pp-placeholder{display:flex;align-items:center;justify-content:center;background:#e6eef9;color:#829bbb}.pp-card h3{font-size:22px;line-height:1.2;letter-spacing:-.6px;color:#0d80d8;margin-bottom:10px}.pp-card:hover h3{text-decoration:underline}.pp-card p{font-size:17px;color:#566178}.pp-count{font-size:13px;color:#566178;margin-bottom:30px}.pp-empty{padding:35px;border:1px solid #dce3ef}.pp-empty h3{font-size:23px;line-height:1.4;margin-bottom:15px}.pp-empty p{color:#566178;line-height:1.6}.pp-text-link{display:inline-flex;align-items:center;gap:12px;padding:0;border:0;background:none;color:#0d80d8;font:inherit;font-size:16px;font-weight:600;cursor:pointer;margin-top:15px}.pp-expertise{display:grid;grid-template-columns:1fr 1fr;gap:30px}.pp-expertise>a{border-top:2px solid #dce3ef;padding-top:20px}.pp-expertise h3{display:flex;align-items:center;gap:15px;color:#0d80d8;font-size:21px;line-height:1.3;margin-bottom:12px}.pp-expertise p{font-size:15px;line-height:1.6;color:#566178}.pp-profile{padding-top:50px;padding-bottom:90px}.pp-profile-grid{display:grid;grid-template-columns:1fr 2fr;gap:70px;margin-top:45px}.pp-profile h2{font-size:30px;margin-bottom:20px;letter-spacing:-1px}.pp-profile p,.pp-profile ul{color:#566178;margin-bottom:12px}.pp-profile .ad-button{margin-top:25px}#people-results:focus-visible{outline:2px solid #0d80d8;outline-offset:12px}@media(max-width:1000px){.pp-overview{gap:35px}.pp-grid{gap:35px}.pp-tabs button{font-size:14px;padding:17px 15px}.pp-filters{gap:20px}.pp-card h3{font-size:19px}}@media(max-width:720px){.pp-hero{padding-top:115px;min-height:420px}.pp-hero-title{padding:50px 0 85px}.pp-hero h1{letter-spacing:-1.5px}.pp-tabs button{padding:16px 13px;font-size:13px}.pp-directory{padding:40px 0}.pp-directory h2{font-size:26px;margin-bottom:25px}.pp-filters{grid-template-columns:1fr 1fr;gap:15px}.pp-filters>label:nth-child(3){grid-column:1/-1}.pp-filters button{justify-self:start}.pp-content{padding:45px 0 60px}.pp-content h2{font-size:31px}.pp-overview{grid-template-columns:1fr;gap:35px}.pp-secondary{gap:25px;margin-bottom:40px}.pp-secondary button{font-size:14px}.pp-grid{grid-template-columns:1fr 1fr;gap:35px 25px}.pp-card p{font-size:15px}.pp-expertise{grid-template-columns:1fr}.pp-profile-grid{grid-template-columns:1fr;gap:35px}.pp-quote blockquote{font-size:24px}}
</style>
